  // Base64 encoded logo image (A1 Water Tech Logo)
  static const String _logoBase64 = '';

  // Base64 encoded signature image (sly signature)
  static const String _signatureBase64 = '';

  static Future<Uint8List> generateInvoice(
    Bill bill, {
    Customer? customer,
    bool isDigitalSignature = true,
  }) async {
    return _buildPdf(bill, false, customer, isDigitalSignature);
  }

  static Future<Uint8List> generateQuotation(
    Quotation quotation, {
    Customer? customer,
    bool isDigitalSignature = true,
  }) async {
    Customer? fetchedCustomer = customer;
    if (fetchedCustomer == null && quotation.customerId != null && quotation.customerId!.isNotEmpty) {
      try {
        fetchedCustomer = await DatabaseService().getCustomerById(quotation.customerId!);
      } catch (e) {
        // Ignore
      }
    }
    return _buildPdf(quotation, true, fetchedCustomer, isDigitalSignature);
  }

  static Future<Uint8List> _buildPdf(
    dynamic document,
    bool isQuotation,
    Customer? customer,
    bool isDigitalSignature,
  ) async {
    final pdf = Document();

    final logoBytes = base64Decode(_logoBase64);
    final signatureBytes = base64Decode(_signatureBase64);

    final logoImage = MemoryImage(logoBytes);
    final signatureImage = MemoryImage(signatureBytes);

    pdf.addPage(
      Page(
        pageFormat: PdfPageFormat.a4,
        margin: const EdgeInsets.symmetric(horizontal: 40, vertical: 30),
        build: (context) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _buildHeader(logoImage, isQuotation),
              SizedBox(height: 15),
              _buildBillingSection(document, customer, isQuotation),
              SizedBox(height: 15),
              _buildItemsTable(document),
              SizedBox(height: 15),
              _buildSummaryRow(document),
              SizedBox(height: 15),
              _buildPaymentAndSignature(document, signatureImage, isDigitalSignature),
            ],
          );
        },
      ),
    );

    return pdf.save();
  }

  static Widget _buildPhoneIcon() {
    return Container(
      width: 7,
      height: 11,
      child: CustomPaint(
        size: const PdfPoint(7, 11),
        painter: (PdfGraphics canvas, PdfPoint size) {
          canvas.setLineWidth(0.5);
          canvas.setStrokeColor(PdfColors.black);
          canvas.drawRRect(0, 0, size.x, size.y, 1, 1);
          canvas.strokePath();
          // Speaker line
          canvas.moveTo(2, size.y - 1.5);
          canvas.lineTo(size.x - 2, size.y - 1.5);
          canvas.strokePath();
          // Home button dot
          canvas.drawEllipse(size.x / 2, 1.25, 0.4, 0.4);
          canvas.strokePath();
        },
      ),
    );
  }

  static Widget _buildEmailIcon() {
    return Container(
      width: 10,
      height: 7,
      child: CustomPaint(
        size: const PdfPoint(10, 7),
        painter: (PdfGraphics canvas, PdfPoint size) {
          canvas.setLineWidth(0.5);
          canvas.setStrokeColor(PdfColors.black);
          canvas.drawRect(0, 0, size.x, size.y);
          canvas.strokePath();
          // Envelope flap
          canvas.moveTo(0, size.y);
          canvas.lineTo(size.x / 2, size.y / 2);
          canvas.lineTo(size.x, size.y);
          canvas.strokePath();
        },
      ),
    );
  }

