  static Widget _buildItemsTable(dynamic bill) {
    return Table(
      border: TableBorder(
        top: const BorderSide(color: PdfColors.grey400, width: 0.5),
        bottom: const BorderSide(color: PdfColors.grey400, width: 0.5),
        horizontalInside: const BorderSide(color: PdfColors.grey300, width: 0.5),
      ),
      columnWidths: const {
        0: FixedColumnWidth(25),  // #
        1: FlexColumnWidth(),      // DESCRIPTION
        2: FixedColumnWidth(55),  // HSN
        3: FixedColumnWidth(35),  // QTY
        4: FixedColumnWidth(50),  // PRICE
        5: FixedColumnWidth(60),  // TAXABLE AMOUNT
        6: FixedColumnWidth(50),  // CGST
        7: FixedColumnWidth(50),  // SGST
        8: FixedColumnWidth(60),  // TOTAL
      },
      children: [
        // Table Header
        TableRow(
          decoration: const BoxDecoration(color: PdfColors.grey100),
          children: [
            _tableHeaderCell('#', align: TextAlign.center),
            _tableHeaderCell('DESCRIPTION'),
            _tableHeaderCell('HSN', align: TextAlign.center),
            _tableHeaderCell('QTY', align: TextAlign.center),
            _tableHeaderCell('PRICE', align: TextAlign.right),
            _tableHeaderCell('TAXABLE\nAMOUNT', align: TextAlign.right),
            _tableHeaderCell('CGST', align: TextAlign.right),
            _tableHeaderCell('SGST', align: TextAlign.right),
            _tableHeaderCell('TOTAL', align: TextAlign.right),
          ],
        ),
        // Table Data Rows
        ...List.generate(bill.items.length, (index) {
          final item = bill.items[index];
          final taxableAmount = item.price * item.quantity;
          final cgstAmount = item.gstAmount / 2;
          final sgstAmount = item.gstAmount / 2;
          final cgstPercent = item.gstPercent / 2;
          final sgstPercent = item.gstPercent / 2;

          return TableRow(
            children: [
              _tableDataCell((index + 1).toString(), align: TextAlign.center),
              _tableDataCell(item.name, align: TextAlign.left, isBold: true),
              _tableDataCell(item.hsn ?? '', align: TextAlign.center),
              _tableDataCell(
                '${item.quantity}\n${item.quantity}${item.type == "service" ? "hr" : "nos"}',
                align: TextAlign.center,
              ),
              _tableDataCell(item.price.toStringAsFixed(2), align: TextAlign.right),
              _tableDataCell(taxableAmount.toStringAsFixed(2), align: TextAlign.right),
              _tableDataCell(
                '${cgstAmount.toStringAsFixed(2)}\n${cgstPercent.toStringAsFixed(1)}%',
                align: TextAlign.right,
              ),
              _tableDataCell(
                '${sgstAmount.toStringAsFixed(2)}\n${sgstPercent.toStringAsFixed(1)}%',
                align: TextAlign.right,
              ),
              _tableDataCell(item.total.toStringAsFixed(2), align: TextAlign.right),
            ],
          );
        }),
      ],
    );
  }

  static Widget _tableHeaderCell(String text, {TextAlign align = TextAlign.left}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 2),
      child: Text(
        text,
        textAlign: align,
        style: TextStyle(
          fontSize: 7.5,
          fontWeight: FontWeight.bold,
          color: PdfColors.black,
        ),
      ),
    );
  }

  static Widget _tableDataCell(String text, {TextAlign align = TextAlign.left, bool isBold = false}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 2),
      child: Text(
        text,
        textAlign: align,
        style: TextStyle(
          fontSize: 7.5,
          fontWeight: isBold ? FontWeight.bold : FontWeight.normal,
          color: PdfColors.black,
        ),
      ),
    );
  }


  static Widget _buildSummaryRow(dynamic bill) {
    final totalInWords = NumberToWords.convertAmount(bill.total);
    bool isQuotation = bill.runtimeType.toString() == 'Quotation';
    
    double roundOffDelta = 0.0;
    if (isQuotation && bill.isRoundedOff) {
      double rawTotal = bill.subtotal + bill.gstAmount + (bill.otherChargeAmount ?? 0) + (bill.isOtherChargeTaxable ? ((bill.otherChargeAmount ?? 0) * (bill.otherChargeGstPercent ?? 0) / 100) : 0);
      roundOffDelta = bill.total - rawTotal;
    }

    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Amount in words on left
        Expanded(
          flex: 3,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'AMOUNT IN WORDS:',
                style: TextStyle(fontSize: 8.5, fontWeight: FontWeight.bold),
              ),
              SizedBox(height: 2),
              Text(
                totalInWords,
                style: const TextStyle(fontSize: 8.5),
              ),
            ],
          ),
        ),
        SizedBox(width: 20),
        // Tax Summary block on right
        Expanded(
          flex: 2,
          child: Column(
            children: [
              _buildSummaryItem('TAXABLE AMOUNT', bill.subtotal),
              SizedBox(height: 2),
              _buildSummaryItem('CGST', bill.gstAmount / 2),
              SizedBox(height: 2),
              _buildSummaryItem('SGST', bill.gstAmount / 2),
              SizedBox(height: 2),
              if (isQuotation && bill.otherChargeAmount != null && bill.otherChargeAmount! > 0) ...[
                _buildSummaryItem((bill.otherChargeLabel?.isNotEmpty ?? false) ? bill.otherChargeLabel!.toUpperCase() : 'OTHER CHARGE', bill.otherChargeAmount!),
                SizedBox(height: 2),
                if (bill.isOtherChargeTaxable) ...[
                  _buildSummaryItem('OTHER CHARGE CGST', (bill.otherChargeAmount! * bill.otherChargeGstPercent! / 100) / 2),
                  SizedBox(height: 2),
                  _buildSummaryItem('OTHER CHARGE SGST', (bill.otherChargeAmount! * bill.otherChargeGstPercent! / 100) / 2),
                  SizedBox(height: 2),
                ],
              ],
              if (isQuotation && bill.isRoundedOff && roundOffDelta != 0.0) ...[
                _buildSummaryItem('ROUND OFF', roundOffDelta),
                SizedBox(height: 2),
              ],
              Container(
                decoration: const BoxDecoration(
                  border: Border(
                    top: BorderSide(color: PdfColors.black, width: 0.5),
                    bottom: BorderSide(color: PdfColors.black, width: 0.5),
                  ),
                ),
                padding: const EdgeInsets.symmetric(vertical: 3),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'GRAND TOTAL',
                      style: TextStyle(fontSize: 9, fontWeight: FontWeight.bold),
                    ),
                    Text(
                      bill.total.toStringAsFixed(2),
                      style: TextStyle(fontSize: 9, fontWeight: FontWeight.bold),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  static Widget _buildSummaryItem(String label, double amount) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(
          label,
          style: const TextStyle(fontSize: 8, color: PdfColors.black),
        ),
        Text(
          amount.toStringAsFixed(2),
          style: const TextStyle(fontSize: 8, color: PdfColors.black),
        ),
      ],
    );
  }

